<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {route} from '../router';
import {jointRuns,jointPlans} from '../stores/joint';
import {fixed} from '../utils/format';
import PageHeading from '../components/common/PageHeading.vue';
import StatusPill from '../components/common/StatusPill.vue';
import Notice from '../components/common/Notice.vue';
import EmptyState from '../components/common/EmptyState.vue';
const selected=ref(route.value.query.get('run')||'demo-joint-run');
watch(()=>route.value.query.get('run'),v=>{selected.value=v||'demo-joint-run'});
let timer:ReturnType<typeof setInterval>;
onMounted(()=>{jointRuns.load();jointPlans.load();timer=setInterval(jointRuns.load,2000)});
onUnmounted(()=>clearInterval(timer));
const run=computed(()=>jointRuns.items.value.find(r=>r.id===selected.value));
const result=computed<any>(()=>run.value?.result);
const planMap=computed<Record<string,any>>(()=>{const map:Record<string,any>={};for(const p of jointPlans.items.value)map[p.id]=p;return map});
function planName(id:string){return planMap.value[id]?.name||String(id).slice(0,8)}
const runStatusLabels:Record<string,string>={optimal:'整包最优',timeout:'限时可行',infeasible:'无方案',undetermined:'未判定',failed:'失败',queued:'排队中',running:'计算中',completed:'已完成'};
function runLabel(r:any){const st=r.result?.status||r.status;return planName(r.plan_id)+' · '+(runStatusLabels[st]||st)}
const failedBeforeSolve=computed(()=>run.value?.status==='failed'&&!result.value?.status);
const statusLabel=computed(()=>{const st=result.value?.status;if(st==='optimal')return '整包最优';if(st==='timeout')return '限时可行解';if(st==='infeasible')return '无同时满足方案';if(st==='undetermined')return '未判定（不判无解）';if(st==='failed')return '计算失败';return run.value?'':''});
const verdict=computed(()=>{
 if(!result.value)return '';
 if(result.value.status==='failed'||result.value.status==='undetermined')return result.value.reason||'求解未完成；不下无解结论。';
 if(result.value.status==='optimal')return '已证明半吨整包整数最优：全部订单同时满足且总成本最低。';
 if(result.value.status==='timeout')return '30秒内未证明最优，以下方案已通过独立约束核验；成本下界与差距一并给出。';
 if(result.value.status==='infeasible')return result.value.diagnosis?.continuous_feasible?'连续配方可行，但0.5吨整包无法同时满足全部订单，整数模型无解。':'连续配方即冲突：共享库存、供给比例与质量窗口无法同时满足，不给方案。';
 if(result.value.status==='undetermined')return '未在限期内找到可核验方案，不能据此判无解，也不冒报无解。';
 return '求解未完成；不下无解结论。';
});
function num(v:any,n=1){return Number(Number(v||0).toFixed(n))}
function pctg(v:any,n=1){return fixed(Number(v||0)*100,n)+'%'}function window(spec:any,key:string){if(!spec||!spec[key])return '—';const scale=key==='recycled'?100:1;const unit=key==='strength'?'':'%';return num(Number(spec[key].min)*scale,key==='recycled'?0:1)+unit+'—'+num(Number(spec[key].max)*scale,key==='recycled'?0:1)+unit}
function used(o:any){return o.lines.filter((l:any)=>l.packs>0)}
function qlabel(key:string){return key==='recycled'?'回收纤维率':(key==='whiteness'?'白度 %':'模拟强度')}
function qfmt(key:string,v:number){return key==='recycled'?fixed(v*100,2)+'%':fixed(v,3)}
function qbound(key:string,v:number){return key==='recycled'?fixed(v*100,1)+'%':fixed(v,1)}
</script>
<template><PageHeading index="07 / 联合运行底稿" title="分单用量、共享库存结余与成本下界。" note="每纸种各原浆用量按0.5吨整包；供给比例与质量界限沿用原浆批次与各订单的质量窗口。下界是全部订单同时满足时总成本不可能低于的值，差距=(方案成本−下界)/方案成本。"/><div class="result-toolbar"><label>联合运行<select v-model="selected"><option v-for="r in jointRuns.items.value" :key="r.id" :value="r.id">{{runLabel(r)}}</option></select></label><StatusPill v-if="run" :status="result?result.status:run.status" :label="statusLabel"/></div><Notice :message="jointRuns.error.value"/><Notice v-if="failedBeforeSolve" :message="run?.error||''"/><EmptyState v-if="run&&['queued','running'].includes(run.status)" text="后台worker正在求半吨整包联合最优；30秒上限，结果每两秒刷新。"/><template v-if="result?.status&&run&&!['queued','running'].includes(run.status)"><p :class="['joint-banner',result.feasible?'ok':'']">{{verdict}}</p><p class="method-note" v-if="result.reason">{{result.reason}}</p><template v-if="result.feasible"><div class="joint-metrics"><div><small>可行方案总成本 / 元</small><strong>{{fixed(result.total_cost)}}</strong><span>{{result.orders.length}} 个订单 · {{num(result.orders.reduce((s:number,o:any)=>s+o.tonnes,0))}} 吨</span></div><div><small>成本下界 / 元</small><strong>{{fixed(result.lower_bound)}}</strong><span>全部订单同时满足时不可能更低</span></div><div><small>成本差距</small><strong>{{fixed((result.gap||0)*100,3)}}%</strong><span>时限 {{result.time_limit_seconds}}秒 · 用时 {{fixed(result.elapsed_seconds,2)}}秒</span></div><div><small>独立核验</small><strong>{{result.verification?.passed?'通过':'未通过'}}</strong><span>整包整数 · 供给比例 · 质量窗口 · 共享库存</span></div></div><section><h2>分单用量</h2><article v-for="o in result.orders" :key="o.order_id" class="order-card"><p class="eyebrow">{{o.order_id}} · {{o.spec_name}}</p><h3>{{o.name}}</h3><dl><div><dt>订单吨数</dt><dd>{{num(o.tonnes)}} 吨</dd></div><div><dt>整包数</dt><dd>{{o.packs}} 包</dd></div><div><dt>本单成本</dt><dd>{{fixed(o.cost)}} 元</dd></div><div><dt>比例和</dt><dd>{{fixed(o.share_sum,6)}}</dd></div></dl><div class="usage-bars"><div v-for="l in used(o)" :key="l.material_id"><b>{{l.name}}</b> {{l.packs}} 包 / {{num(l.tonnes)}} 吨 · {{fixed(l.share*100,1)}}%<i><em :style="{width:Math.min(100,l.packs/o.packs*100)+'%'}"></em></i></div></div><div class="table-wrap"><table><thead><tr><th>原浆</th><th>整包</th><th>吨数</th><th>比例</th><th>供给下限</th><th>供给上限</th><th>本行成本</th></tr></thead><tbody><tr v-for="l in used(o)" :key="l.material_id"><td>{{l.name}} <small>{{l.material_id}}</small></td><td>{{l.packs}}</td><td>{{num(l.tonnes)}}</td><td>{{fixed(l.share*100,1)}}%</td><td>{{fixed(l.min_share*100,1)}}%</td><td>{{fixed(l.max_share*100,1)}}%</td><td>{{fixed(l.line_cost)}}</td></tr></tbody></table></div><div class="table-wrap"><table><thead><tr><th>质量属性</th><th>加权值</th><th>下界</th><th>上界</th><th>下界余量</th><th>上界余量</th></tr></thead><tbody><tr v-for="q in o.qualities" :key="q.property"><td>{{qlabel(q.property)}}</td><td>{{qfmt(q.property,q.value)}}</td><td>{{qbound(q.property,q.minimum)}}</td><td>{{qbound(q.property,q.maximum)}}</td><td>{{qfmt(q.property,q.lower_slack)}}</td><td>{{qfmt(q.property,q.upper_slack)}}</td></tr></tbody></table></div></article></section><section><h2>共享库存结余</h2><div class="table-wrap"><table class="inventory-table"><thead><tr><th>原浆</th><th>库存 吨</th><th>已用包数</th><th>已用 吨</th><th>结余 吨</th><th>单价 元/吨</th></tr></thead><tbody><tr v-for="i in result.inventory" :key="i.material_id"><td>{{i.name}} <small>{{i.material_id}}</small></td><td class="num">{{num(i.inventory_tonnes)}}</td><td class="num">{{i.used_packs}}</td><td class="num">{{num(i.used_tonnes)}}</td><td class="num" :class="{zero:i.remaining_tonnes<1e-9}">{{num(i.remaining_tonnes)}}</td><td class="num">{{fixed(i.unit_cost,0)}}</td></tr></tbody></table></div><p class="method-note">共享库存约束已计入整数模型：各纸种同一原浆用量之和不超过录入库存；结余=库存−已用。全部用量为0.5吨整包的整数倍。</p></section><section><h2>核验与求解器记录</h2><ul class="verify-list"><li v-for="c in result.verification?.checked" :key="c">{{c}}：通过</li><li v-for="f in result.verification?.failures" :key="f">{{f}}</li><li>比较绝对容差 {{result.comparison_tolerance}}；整包单位 {{result.pack_tonnes}} 吨。</li><li>求解阶段 {{result.solver?.stage}} · 状态 {{result.solver?.status}} · 节点 {{result.solver?.node_count}} · 对偶界 {{result.solver?.dual_bound===null||result.solver?.dual_bound===undefined?'—':fixed(result.solver?.dual_bound)}} · 整数松弛下界 {{result.solver?.integer_relaxation_lower_bound===undefined?'—':fixed(result.solver?.integer_relaxation_lower_bound)}}。</li><li v-if="result.status==='timeout'">超时降级：未证明最优，但该方案已逐项核验；差距 {{fixed((result.gap||0)*100,4)}}% 是方案成本相对下界的最大可改进幅度。</li><li>{{result.gap_definition}}</li><li>{{result.assumption}}</li></ul></section></template><template v-else><section><h2>输入订单与质量窗口</h2><div class="table-wrap"><table><thead><tr><th>订单</th><th>纸种</th><th>吨数</th><th>整包数</th><th>质量窗口</th><th>强度</th><th>白度</th><th>回收率</th></tr></thead><tbody><tr v-for="o in (result.orders_input||result.diagnosis?.orders||[])" :key="o.order_id"><td>{{o.order_id}}</td><td>{{o.name}}</td><td>{{num(o.tonnes)}}</td><td>{{o.packs}}</td><td>{{o.spec_name}}</td><td>{{window(o.spec,'strength')}}</td><td>{{window(o.spec,'whiteness')}}</td><td>{{window(o.spec,'recycled')}}</td></tr></tbody></table></div></section><section><h2>无方案的依据</h2><p>{{result.reason}}</p><ul class="verify-list"><li v-if="result.diagnosis?.totals">订单合计 {{num(result.diagnosis.totals.demand_tonnes)}} 吨，录入库存合计 {{num(result.diagnosis.totals.inventory_tonnes)}} 吨。</li><li>连续配方可行性：{{result.diagnosis?.continuous_feasible===true?'可行':(result.diagnosis?.continuous_feasible===false?'不可行':'未判定')}}</li><li v-if="result.diagnosis?.per_order">逐单宽松核验（含各自可用库存）：{{result.diagnosis.per_order.map((o:any)=>o.order_id+(o.alone_continuous_feasible===true?' 可行':(o.alone_continuous_feasible===false?' 不可行':' 未判定'))).join('；')}}。<span v-if="result.diagnosis?.continuous_feasible===false&&result.diagnosis.per_order.length>1">单看每单可行、合在一起不可行，说明冲突来自共享同一批原浆库存。</span><span v-if="result.diagnosis?.continuous_feasible===true&&result.diagnosis?.pack_feasible===false&&result.diagnosis.per_order.length===1">单看该单连续可行，整包不可行，说明冲突来自0.5吨取整而非质量模型本身。</span></li><li>半吨整包可行性：{{result.diagnosis?.pack_feasible===true?'可行':(result.diagnosis?.pack_feasible===false?'不可行':'未判定')}}</li><li v-if="result.diagnosis?.pack_feasible===false&&result.diagnosis?.continuous_feasible===true">整包无解不等于无任何配方：连续比例可行，但0.5吨整包取整后质量窗口无法同时满足。</li><li v-if="result.lower_bound!==null&&result.lower_bound!==undefined">成本下界 {{fixed(result.lower_bound)}} 元；未找到可核验方案，因此不公布差距。</li><li>用时 {{fixed(result.elapsed_seconds,2)}} 秒，时限 {{result.time_limit_seconds}} 秒。</li></ul><div v-if="result.diagnosis?.inventory_shortfalls?.length" class="table-wrap"><p class="method-note">供给比例下界所需的最低用量已超过库存；这是连续冲突的直接证据。</p><table><thead><tr><th>原浆</th><th>库存 吨</th><th>各单比例下界所需 吨</th><th>缺口 吨</th></tr></thead><tbody><tr v-for="u in result.diagnosis.inventory_shortfalls" :key="u.material_id"><td>{{u.name}} <small>{{u.material_id}}</small></td><td>{{num(u.inventory_tonnes)}}</td><td>{{num(u.minimum_required_tonnes)}}</td><td>{{num(u.shortfall_tonnes)}}</td></tr></tbody></table></div></section></template></template></template>
